import std.io
import std.collections

pub type AppError = Failed(String)

record Cell { hi: Int64 }

pub fn main() effect io -> Result<(), AppError> {
    let m = collections.mapOf(["k0", "k1"], [Cell { hi: 7 }, Cell { hi: 8 }])
    var i: Int64 = 0
    while i < 60000 {
        let t = Cell { hi: i }
        i = i + 1
    }
    match m.get("k0") {
        Some(c) => { io.println("k0:${c.hi}") }
        None => { io.println("k0:none") }
    }
    match m.get("k1") {
        Some(c) => { io.println("k1:${c.hi}") }
        None => { io.println("k1:none") }
    }
    io.println("size:${m.size()}")
    return Ok(())
}
